[options]
mode prove
depth 110

[engines]
smtbmc

[script]
read -formal deep_counter.v
read -formal deep_counter_props.sv
prep -top deep_counter_props

[files]
deep_counter.v
deep_counter_props.sv
=== END FILE ===

=== FILE: deep_counter_props.sv ===
// Formal properties for deep_counter, written against interface_spec.md.
// Each assertion states one interface rule (req tags in comments).
// No assumptions: inputs are left free to the solver.
// Immediate-form assertions only, as the open Yosys front end reads them.
`default_nettype none
module deep_counter_props #(
    parameter integer LIMIT = 99
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    wire [6:0] count;
    wire       carry;

    deep_counter #(.LIMIT(LIMIT)) dut (
        .clk  (clk),
        .rst_n(rst_n),
        .en   (en),
        .clr  (clr),
        .count(count),
        .carry(carry)
    );

    localparam [6:0] F_LAST = LIMIT;

    // First-cycle guard for $past, and a flag for "a reset edge has happened".
    reg f_past_valid;
    reg f_reset_seen;
    initial f_past_valid = 1'b0;
    initial f_reset_seen = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_seen <= 1'b1;
    end

    // [req:DC-CARRY] carry is high exactly when en, !clr and count == LIMIT,
    // combinationally.
    always @(*)
        assert(carry == (en && !clr && (count == F_LAST)));

    // [req:DC-RANGE] after reset, count never exceeds LIMIT.
    // Also the helper invariant that makes the induction step close.
    always @(*)
        if (f_reset_seen)
            assert(count <= F_LAST);

    // Next-state rules, checked one edge after the inputs they describe.
    always @(posedge clk)
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert(count == 7'd0);                      // [req:DC-RESET]
            else if ($past(clr))
                assert(count == 7'd0);                      // [req:DC-CLEAR], whatever en is
            else if ($past(en)) begin
                if ($past(count) == F_LAST)
                    assert(count == 7'd0);                  // [req:DC-COUNT] wrap
                else if ($past(count) < F_LAST)
                    assert(count == $past(count) + 7'd1);   // [req:DC-COUNT] step
            end else
                assert(count == $past(count));              // [req:DC-HOLD]
        end

    // Covers: scenarios the proof must still allow (vacuity check).
    always @(posedge clk) begin
        if (f_reset_seen) begin
            cover(count == F_LAST);   // reaches the last count
            cover(count[6]);          // top bit of count exercised
            cover(carry);             // carry out asserted
        end
        // Wrap from LIMIT to 0 on an enabled edge.
        if (f_past_valid && $past(f_reset_seen) && $past(rst_n) && !$past(clr)
                && $past(en) && ($past(count) == F_LAST))
            cover(count == 7'd0);
        // Clear while counting, with en high at the same edge.
        if (f_past_valid && $past(f_reset_seen) && $past(rst_n) && $past(clr)
                && $past(en) && ($past(count) != 7'd0))
            cover(count == 7'd0);
        // Reset in the middle of a count.
        if (f_past_valid && $past(f_reset_seen) && !$past(rst_n)
                && ($past(count) != 7'd0))
            cover(count == 7'd0);
    end
endmodule
`default_nettype wire
=== END FILE ===
